import React, { useState, useEffect, useRef } from 'react';
// Import from a CDN to resolve the module error
import { Link as ScrollLink } from 'https://esm.sh/react-scroll';
import {
    Box, Menu, Linkedin, Twitter, Github, Mail, Phone, Facebook, Instagram, Home, Info, Users, Folder, Activity, TrendingUp, Settings, MapPin
// Import from a CDN to resolve the module error
} from 'https://esm.sh/react-feather';

// Removed the CSS import, as we will now inline it.
// import "./Aiiot_index.css";

//==============================================================================
// 0. INLINED STYLES
// We're adding the CSS directly into the component to fix the import error.
//==============================================================================
const AppStyles = () => (
  <style>{`
    /* This is the CSS from the <style> tag in your original index.html.
      It's required for the fonts, scrollbar, animations, and carousel to work.
    */

    /* Set the default font for the entire page */
    body {
        font-family: 'Inter', sans-serif;
        background-color: #f8fafc; /* A slightly cooler light gray (slate-50) */
        /* Antialiasing for smoother fonts */
        -webkit-font-smoothing: antialiased;
        -moz-osx-font-smoothing: grayscale;
    }

    /* Custom scrollbar for a polished look */
    ::-webkit-scrollbar { width: 10px; }
    ::-webkit-scrollbar-track { background: #e2e8f0; /* slate-200 */ }
    ::-webkit-scrollbar-thumb {
        background-color: #3b82f6; /* blue-500 */
        border-radius: 20px;
        border: 3px solid #e2e8f0; /* slate-200 */
    }
    ::-webkit-scrollbar-thumb:hover { background-color: #2563eb; /* blue-600 */ }

    /* A subtle gradient for the hero section background */
    .hero-gradient {
        background: linear-gradient(135deg, rgba(255, 255, 255, 1) 0%, rgba(240, 245, 255, 1) 100%);
    }

    /* Animation for cards and sections on scroll */
    .reveal-on-scroll {
        opacity: 0;
        transform: translateY(30px);
        transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .reveal-on-scroll.is-visible {
        opacity: 1;
        transform: translateY(0);
    }

    /* Hero Image Carousel Styles - targeting the new React ID */
    #hero-image-react {
        transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out;
    }
    #hero-image-react.is-fading {
        opacity: 0.4;
        transform: scale(1.03);
    }

    .indicator { transition: all 0.3s ease-in-out; }
    .indicator:hover {
        transform: scale(1.3);
        opacity: 0.8;
    }
    .indicator.active { 
        animation: pulse 1s infinite alternate; 
        transform: scale(1.1);
    }

    @keyframes pulse {
        from { opacity: 1; transform: scale(1.1); }
        to { opacity: 0.7; transform: scale(1); }
    }
  `}</style>
);


//==============================================================================
// 1. CUSTOM HOOK FOR SCROLL ANIMATIONS
// (This was perfect, no changes needed)
//==============================================================================
const useRevealOnScroll = (options) => {
    const [isVisible, setIsVisible] = useState(false);
    const ref = useRef(null);

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                    observer.unobserve(entry.target);
                }
            },
            { threshold: 0.1, ...options }
        );

        const currentRef = ref.current;
        if (currentRef) {
            observer.observe(currentRef);
        }

        return () => {
            if (currentRef) {
                observer.unobserve(currentRef);
            }
        };
    }, [options]);

    return {
        ref: ref,
        // The CSS class 'reveal-on-scroll' is now defined in the <AppStyles> component
        className: `reveal-on-scroll ${isVisible ? 'is-visible' : ''}`
    };
};


//==============================================================================
// 2. DATA FOR COMPONENTS
// (This was perfect, no changes needed)
//==============================================================================
const facultyData = [
    { name: 'Dr. Ajay Kumar', role: 'Principal Investigator', img: '/faculties/ajay.jpeg', link: 'https://www.adishankara.ac.in/department/faculty/25', description: 'Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.', socials: { linkedin: '#', twitter: '#' } },
    { name: 'Mr. Albins Paul', role: 'Co-Investigator', img: '/faculties/albins.jpg', link: 'https://www.adishankara.ac.in/department/faculty/66', description: "Assistant Professor at ASIET's ECE Department, specializing in Microwave & Television Engineering.", socials: { linkedin: '#', github: '#' } },
    { name: 'Prof. P.V. Rajaraman', role: 'Co-Investigator', img: '/faculties/rajaraman.jpg', link: 'https://www.adishankara.ac.in/department/faculty/375', description: 'Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.', socials: { linkedin: '#', twitter: '#' } },
    { name: 'Mr. Abhijith Pm', role: 'Project Associate', img: '/faculties/abhijith.jpeg', link: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in', socials: { linkedin: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in', twitter: '#' } },
    { name: 'Mrs. Hasna Hameed', role: 'Project Associate', img: '/faculties/hasna2.JPG', link: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/', socials: { linkedin: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/', twitter: '#' } },
    { name: 'Ms. Arathy Surendran', role: 'Project Assistant', img: '/faculties/arathy.JPG', link: 'https://www.linkedin.com/in/arathy-surendran/', socials: { linkedin: 'https://www.linkedin.com/in/arathy-surendran/', twitter: '#' } },
    { name: 'Mr. Bhagyaraj J', role: 'Project Assistant', img: '/faculties/bhagyaraj.jpeg', link: '#', socials: { linkedin: '#', github: '#' } },
    { name: 'Mr. Amaljith N Raj', role: 'Project Assistant', img: '/faculties/amaljith.JPG', link: '#', socials: { linkedin: '#', github: '#' } },
    { name: 'Mrs. Jebina EA', role: 'Project Assistant', img: '/faculties/jibinaea.jpeg', link: '#', socials: { linkedin: '#', github: '#' } },
];

const projectData = [
    { title: 'Intelligent Sensor Module', img: '/sensor_modules/module3.jpg', description: 'Developing a smart sensor module for real-time monitoring and management of environmental pollutants.' },
    { title: 'Smart Water Level Monitoring', img: '/sensor_modules/water.png', description: 'A robust solution for monitoring water levels with an integrated alert system to mitigate flood risks.' },
    { title: 'Digital Water Distribution', img: '/sensor_modules/water_authorityy.jpeg', description: 'Creating a digital twin to efficiently monitor and manage water distribution networks in urban areas.' },
    { title: 'Startup & Skill Development', img: '/sensor_modules/skill.jpg', description: 'Fostering a vibrant startup ecosystem and providing skill development programs centered around our IoT solutions.' },
    { title: 'Explainable AI Software', img: '/sensor_modules/ai.jpeg', description: 'Building analysis software based on Explainable AI (XAI) to bring transparency and trust to complex IoT systems.' },
];


//==============================================================================
// 3. SECTION COMPONENTS
//==============================================================================

const Header = () => {
    // Mobile menu state
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

    const navLinks = [
        { id: 'about', title: 'About' },
        { id: 'faculty', title: 'Faculty' },
        { id: 'projects', title: 'Projects' },
        { id: 'contact', title: 'Contact' },
    ];
    return (
        <header className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-lg border-b border-slate-200/80">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <nav className="flex justify-between items-center h-16">
                    <a href="#" className="flex items-center gap-2 text-xl md:text-2xl font-bold text-blue-600">
                        <Box size={28} />
                        <span className="hidden sm:inline">Center for AI-IoT Innovation</span>
                        <span className="sm:hidden">AI-IoT Center</span>
                    </a>
                    {/* Desktop Menu */}
                    <div className="hidden md:flex items-center space-x-4">
                        <ul className="flex items-center space-x-8">
                            {navLinks.map(link => (
                                <li key={link.id}>
                                    <ScrollLink to={link.id} spy={true} smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300">
                                        {link.title}
                                    </ScrollLink>
                                </li>
                            ))}
                        </ul>
                        <div className="flex items-center space-x-2">
                           <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AirAware</a>
                           <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AWS</a>
                        </div>
                    </div>
                    {/* Mobile Menu Button */}
                    <button 
                        className="md:hidden text-slate-600 hover:text-blue-600" 
                        aria-label="Open menu"
                        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                    >
                        <Menu />
                    </button>
                </nav>
            </div>
            {/* Mobile Menu Dropdown (basic implementation) */}
            {isMobileMenuOpen && (
                <div className="md:hidden bg-white/95 backdrop-blur-lg border-t border-slate-200">
                    <ul className="flex flex-col items-center space-y-4 p-4">
                        {navLinks.map(link => (
                            <li key={link.id}>
                                <ScrollLink 
                                    to={link.id} 
                                    spy={true} 
                                    smooth={true} 
                                    offset={-70} 
                                    duration={500} 
                                    className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300"
                                    onClick={() => setIsMobileMenuOpen(false)} // Close menu on click
                                >
                                    {link.title}
                                </ScrollLink>
                            </li>
                        ))}
                    </ul>
                    <div className="flex justify-center items-center space-x-2 p-4 border-t border-slate-200">
                       <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md">AirAware</a>
                       <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md">AWS</a>
                    </div>
                </div>
            )}
        </header>
    );
};

const Hero = () => {
    const [images, setImages] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isFading, setIsFading] = useState(false);
    const intervalRef = useRef(null);

    const revealTitleProps = useRevealOnScroll();
    const revealTextProps = useRevealOnScroll();
    const revealButtonsProps = useRevealOnScroll();
    const revealImageProps = useRevealOnScroll();

    useEffect(() => {
        fetch('/carousel-images/carousel-images.json')
            .then(res => {
                if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
                return res.json();
            })
            .then(data => setImages(data))
            .catch(err => {
                console.error("Could not load carousel images:", err);
                // Set fallback image if fetch fails
                setImages([{ 
                    src: 'https://placehold.co/1200x600/f0f9ff/334155?text=Image+Not+Available', 
                    alt: 'Image not available' 
                }]);
            });
    }, []);

    const changeSlide = (newIndex) => {
        if (newIndex === currentIndex) return;
        setIsFading(true);
        setTimeout(() => {
            setCurrentIndex(newIndex);
            setIsFading(false);
        }, 500); // This duration should match the CSS transition
    };

    const nextSlide = () => {
        const newIndex = (currentIndex + 1) % images.length;
        changeSlide(newIndex);
    };

    const startAutoSlide = () => {
        clearInterval(intervalRef.current);
        if (images.length > 1) { // Only slide if there's more than one image
            intervalRef.current = setInterval(() => {
                const newIndex = (currentIndexRef.current + 1) % images.length;
                changeSlide(newIndex);
            }, 4000);
        }
    };

    // Use a ref to keep track of currentIndex for the interval
    const currentIndexRef = useRef(currentIndex);
    useEffect(() => {
        currentIndexRef.current = currentIndex;
    }, [currentIndex]);


    useEffect(() => {
        if (images.length > 1) {
            intervalRef.current = setInterval(() => {
                // Read from the ref, not the state, to avoid stale closure
                const newIndex = (currentIndexRef.current + 1) % images.length;
                changeSlide(newIndex);
            }, 4000);
        }
        return () => clearInterval(intervalRef.current);
    }, [images.length]); // Only re-run if image count changes

    // Get the current image details, with a fallback
    const currentImage = images[currentIndex] || { 
        src: 'https://placehold.co/1200x600/f0f9ff/334155?text=Loading...', 
        alt: 'Loading image' 
    };

    return (
        <section id="hero" className="relative hero-gradient py-20 md:py-32">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h1 {...revealTitleProps} className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight">
                    <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
                    <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                </h1>
                <p {...revealTextProps} className="text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto" style={{ transitionDelay: '150ms' }}>
                    The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div {...revealButtonsProps} className="flex flex-col sm:flex-row justify-center items-center gap-4 mb-12" style={{ transitionDelay: '300ms' }}>
                    <ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105">Explore Projects</ScrollLink>
                    <ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer w-full sm:w-auto bg-white hover:bg-slate-100 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105">Learn More</ScrollLink>
                </div>
                <div {...revealImageProps} className="relative max-w-5xl mx-auto" style={{ transitionDelay: '450ms' }}>
                    <div className="absolute -inset-2 bg-gradient-to-r from-blue-400 to-indigo-500 rounded-2xl blur-lg opacity-25"></div>
                    <div className="relative w-full h-auto overflow-hidden rounded-xl shadow-2xl">
                        {/* We use a new ID 'hero-image-react' to apply CSS transitions.
                          The 'is-fading' class triggers the animation defined in Aiiot_index.css 
                        */}
                        <img 
                            id="hero-image-react"
                            src={currentImage.src} 
                            alt={currentImage.alt} 
                            className={`w-full h-auto object-cover ${isFading ? 'is-fading' : ''}`}
                        />
                    </div>
                    {images.length > 1 && (
                        <div className="flex justify-center mt-6 space-x-3">
                            {images.map((_, index) => (
                                <div 
                                    key={index} 
                                    onClick={() => changeSlide(index)} 
                                    // The 'indicator' and 'active' classes are styled in Aiiot_index.css
                                    className={`indicator w-3 h-3 rounded-full cursor-pointer ${currentIndex === index ? 'bg-blue-600 active' : 'bg-blue-300'}`}
                                ></div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </section>
    );
};

